mapper.select:
SELECT po.id AS poId, po.total_amount AS totalAmount, COALESCE(SUM(a.amount), 0) AS paidAmount, po.total_amount - COALESCE(SUM(a.amount), 0) AS unpaidAmount FROM purchase_order po JOIN payment_alloc a ON a.alloc_biz_id = po.id AND a.alloc_biz_type = 'PURCHASE' JOIN payment_record pr ON a.payment_id = pr.id WHERE pr.status = 'NORMAL' AND pr.deleted = 0 AND po.id IN
#{poId}
GROUP BY po.id, po.total_amount
